```php
<?php

/**
 * ShoppingCart - A simple shopping cart implementation
 */
class ShoppingCart
{
    /**
     * @var array Stores cart items with their details
     */
    private array $items = [];

    /**
     * Add an item to the cart.
     * If the item already exists, its quantity is increased.
     *
     * @param string $id       Unique product identifier
     * @param string $name     Product name
     * @param float  $price    Product price
     * @param int    $quantity Quantity to add (default: 1)
     *
     * @throws InvalidArgumentException If price or quantity is invalid
     */
    public function addItem(string $id, string $name, float $price, int $quantity = 1): void
    {
        if ($price < 0) {
            throw new InvalidArgumentException("Price cannot be negative.");
        }

        if ($quantity <= 0) {
            throw new InvalidArgumentException("Quantity must be greater than zero.");
        }

        if (isset($this->items[$id])) {
            $this->items[$id]['quantity'] += $quantity;
        } else {
            $this->items[$id] = [
                'id'       => $id,
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Remove an item from the cart.
     * Decreases quantity by the given amount, or removes it entirely.
     *
     * @param string   $id       Unique product identifier
     * @param int|null $quantity Quantity to remove (null removes all)
     *
     * @throws InvalidArgumentException If quantity is invalid
     * @throws OutOfRangeException      If item is not found in the cart
     */
    public function removeItem(string $id, ?int $quantity = null): void
    {
        if (!isset($this->items[$id])) {
            throw new OutOfRangeException("Item '{$id}' not found in cart.");
        }

        if ($quantity !== null && $quantity <= 0) {
            throw new InvalidArgumentException("Quantity to remove must be greater than zero.");
        }

        // Remove all if no quantity specified or quantity >= current quantity
        if ($quantity === null || $quantity >= $this->items[$id]['quantity']) {
            unset($this->items[$id]);
        } else {
            $this->items[$id]['quantity'] -= $quantity;
        }
    }

