## Key Design Decisions

| Feature | Detail |
|---|---|
| **Item storage** | Keyed by product ID for O(1) lookups and automatic deduplication |
| **Quantity merging** | Adding an existing item increments quantity instead of duplicating |
| **Partial removal** | `removeItem()` accepts an optional quantity for granular control |
| **Input validation** | Throws `InvalidArgumentException` for negative prices or zero quantities |
| **Precision** | `getTotal()` uses `round()` to avoid floating-point drift |

## ShoppingCart PHP Class

```php
<?php

/**
 * ShoppingCart - A simple shopping cart implementation
 */
class ShoppingCart
{
    /**
     * @var array Stores cart items with their details
     */
    private array $items = [];

    /**
     * Add an item to the cart.
     * If the item already exists, its quantity is increased.
     *
     * @param string $id       Unique product identifier
     * @param string $name     Product name
     * @param float  $price    Product price
     * @param int    $quantity Quantity to add (default: 1)
     *
     * @throws InvalidArgumentException If price or quantity is invalid
     */
    public function addItem(string $id, string $name, float $price, int $quantity = 1): void
    {
        if ($price < 0) {
            throw new InvalidArgumentException("Price cannot be negative.");
        }

        if ($quantity <= 0) {
            throw new InvalidArgumentException("Quantity must be greater than zero.");
        }

        if (isset($this->items[$id])) {
            $this->items[$id]['quantity'] += $quantity;
        } else {
            $this->items[$id] = [
                'id'       => $id,
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Remove an item from the cart.
     * Optionally specify a quantity to reduce; omit to remove entirely.
     *
     * @param string   $id       Unique product identifier
     * @param int|null $quantity Quantity to remove (null = remove all)
     *
     * @throws InvalidArgumentException If quantity is invalid
     * @throws OutOfRangeException      If item is not found in the cart
     */
    public function removeItem(string $id, ?int $quantity = null): void
    {
        if (!isset($this->items[$id])) {
            throw new OutOfRangeException("Item '{$id}' not found in cart.");
        }

        if ($quantity !== null && $quantity <= 0) {
            throw new InvalidArgumentException("Quantity to remove must be greater than zero.");
        }

        if ($quantity === null || $quantity >= $this->items[$id]['quantity']) {
            unset($this->items[$id]);
        } else {
            $this->items[$id]['quantity'] -= $quantity;
        }
    }

    /**
     * Get the total price of all items in the cart.
     *
     * @return float Total price rounded to 2 decimal places
     */
    public function getTotal(): float
    {
        $total = array_reduce($this->items, function (float $carry, array $item): float {
            return $carry + ($item['price'] * $item['quantity']);
        }, 0.0);

        return round($total, 2);
    }

    /**
     * Get all items currently in the cart.
     *
     * @return array List of cart items
     */
    public function getItems(): array
    {
        return array_values($this->items);
    }

    /**
     * Get a single item by its ID.
     *
     * @param string $id Unique product identifier
     *
     * @return array|null Item details or null if not found
     */
    public function getItem(string $id): ?array
    {
        return $this->items[$id] ?? null;
    }

    /**
     * Get the total number of individual items (sum of quantities).
     *
     * @return int Total item count
     */
    public function getItemCount(): int
    {
        return array_sum(array_column($this->items, 'quantity'));
    }

    /**
     * Check if the cart is empty.
     *
     * @return bool True if cart has no items
     */
    public function isEmpty(): bool
    {
        return empty($this->items);
    }

    /**
     * Clear all items from the cart.
     */
    public function clear(): void
    {
        $this->items = [];
    }
}
