    public function removeItem(string $name, ?int $quantity = null): void
    {
        $name = trim($name);

        if (!isset($this->items[$name])) {
            throw new InvalidArgumentException("Item '{$name}' not found in cart.");
        }

        if ($quantity !== null && $quantity <= 0) {
            throw new InvalidArgumentException("Quantity to remove must be greater than zero.");
        }

        if ($quantity === null || $quantity >= $this->items[$name]['quantity']) {
            unset($this->items[$name]);
        } else {
            $this->items[$name]['quantity'] -= $quantity;
        }
    }

