        }

        if ($quantity < 1) {
            throw new InvalidArgumentException("Quantity must be at least 1.");
        }

        if (isset($this->items[$id])) {
            // Item already exists — increase the quantity
            $this->items[$id]['quantity'] += $quantity;
        } else {
            $this->items[$id] = [
