```php
<?php

/**
 * Represents a single item in the shopping cart
 */
class CartItem
{
    public function __construct(
        private readonly string $id,
        private readonly string $name,
        private float $price,
        private int $quantity = 1
    ) {
        $this->validatePrice($price);
        $this->validateQuantity($quantity);
    }

    public function getId(): string
    {
        return $this->id;
    }

    public function getName(): string
    {
        return $this->name;
    }

    public function getPrice(): float
    {
        return $this->price;
    }

    public function getQuantity(): int
    {
        return $this->quantity;
    }

    public function getSubtotal(): float
    {
        return round($this->price * $this->quantity, 2);
    }

    public function setQuantity(int $quantity): void
    {
        $this->validateQuantity($quantity);
        $this->quantity = $quantity;
    }

    public function setPrice(float $price): void
    {
        $this->validatePrice($price);
        $this->price = $price;
    }

    private function validatePrice(float $price): void
    {
        if ($price < 0) {
            throw new InvalidArgumentException("Price cannot be negative.");
        }
    }

    private function validateQuantity(int $quantity): void
    {
        if ($quantity < 1) {
            throw new InvalidArgumentException("Quantity must be at least 1.");
        }
    }

    public function toArray(): array
    {
        return [
            'id'       => $this->id,
            'name'     => $this->name,
            'price'    => $this->price,
            'quantity' => $this->quantity,
            'subtotal' => $this->getSubtotal(),
        ];
    }
}

/**
 * Manages a collection of CartItems
 */
class ShoppingCart
{
    /** @var CartItem[] */
    private array $items = [];

    private float $discountAmount = 0.0;

    // -------------------------------------------------------------------------
    // Core Methods
    // -------------------------------------------------------------------------

    /**
     * Add an item to the cart.
     * If the item already exists, its quantity is incremented.
     *
     * @param string $id       Unique product identifier
     * @param string $name     Product name
     * @param float  $price    Unit price
     * @param int    $quantity Number of units to add
     */
    public function addItem(string $id, string $name, float $price, int $quantity = 1): self
    {
        if (isset($this->items[$id])) {
            // Increase quantity if item already in cart
            $newQty = $this->items[$id]->getQuantity() + $quantity;
            $this->items[$id]->setQuantity($newQty);
        } else {
            $this->items[$id] = new CartItem($id, $name, $price, $quantity);
        }

        return $this; // Fluent interface
    }

    /**
     * Remove an item from the cart entirely, or reduce its quantity.
     *
     * @param string   $id             Product identifier
     * @param int|null $quantity       Units to remove (null = remove all)
     */
    public function removeItem(string $id, ?int $quantity = null): self
    {
        if (!isset($this->items[$id])) {
            throw new RuntimeException("Item '{$id}' not found in cart.");
        }

        if ($quantity === null || $quantity >= $this->items[$id]->getQuantity()) {
            // Remove item entirely
            unset($this->items[$id]);
        } else {
            // Reduce quantity
            $newQty = $this->items[$id]->getQuantity() - $quantity;
            $this->items[$id]->setQuantity($newQty);
        }

        return $this;
    }

    /**
     * Update the quantity of an existing item.
     *
     * @param string $id       Product identifier
     * @param int    $quantity New quantity
     */
    public function updateQuantity(string $id, int $quantity): self
    {
        if (!isset($this->items[$id])) {
            throw new RuntimeException("Item '{$id}' not found in cart.");
        }

        $this->items[$id]->setQuantity($quantity);

        return $this;
    }

    // -------------------------------------------------------------------------
    // Totals & Summary
    // -------------------------------------------------------------------------

    /**
     * Get the subtotal before any discount.
     */
    public function getSubtotal(): float
    {
        return round(
            array_sum(array_map(fn(CartItem $item) => $item->getSubtotal(), $this->items)),
            2
        );
    }

    /**
     * Apply a flat discount amount.
     */
    public function applyDiscount(float $amount): self
    {
        if ($amount < 0) {
            throw new InvalidArgumentException("Discount cannot be negative.");
        }

        $this->discountAmount = $amount;

        return $this;
    }

    /**
     * Get the final total after discount (never negative).
     */
    public function getTotal(): float
    {
        return round(max(0, $this->getSubtotal() - $this->discountAmount), 2);
    }

    /**
     * Get the number of unique items in the cart.
     */
    public function getItemCount(): int
    {
        return count($this->items);
    }

    /**
     * Get the total number of units across all items.
     */
    public function getTotalUnits(): int
    {
        return array_sum(array_map(fn(CartItem $item) => $item->getQuantity(), $this->items));
    }

    /**
     * Check whether the cart contains a specific item.
     */
    public function hasItem(string $id): bool
    {
        return isset($this->items[$id]);
    }

    /**
     * Check whether the cart is empty.
     */
    public function isEmpty(): bool
    {
        return empty($this->items);
    }

    /**
     * Empty the cart completely.
     */
    public function clear(): self
    {
        $this->items         = [];
        $this->discountAmount = 0.0;

        return $this;
    }

    /**
     * Return a summary array of the cart.
     */
    public function getSummary(): array
    {
        return [
            'items'      => array_map(fn(CartItem $item) => $item->toArray(), $this->items),
            'item_count' => $this->getItemCount(),
            'total_units'=> $this->getTotalUnits(),
            'subtotal'   => $this->getSubtotal(),
            'discount'   => $this->discountAmount,
            'total'      => $this->getTotal(),
        ];
    }
}
