Here's a robust `slugify()` function that handles various edge cases including Unicode characters, special characters, and multiple separators:

```php
<?php

/**
 * Converts a string into a URL-safe slug.
 *
 * @param string $string    The input string to slugify
 * @param string $separator The word separator (default: '-')
 * @param string $language  The language for transliteration (default: 'en')
 * @return string           The slugified string
 */
function slugify(string $string, string $separator = '-', string $language = 'en'): string
{
    if (empty(trim($string))) {
        return '';
    }

    // 1. Convert to UTF-8 if not already
    if (mb_detect_encoding($string, 'UTF-8', true) === false) {
        $string = mb_convert_encoding($string, 'UTF-8');
    }

    // 2. Replace language-specific characters before transliteration
    $languageMap = [
        'en' => [],
        'de' => ['ä' => 'ae', 'ö' => 'oe', 'ü' => 'ue', 'Ä' => 'Ae', 'Ö' => 'Oe', 'Ü' => 'Ue', 'ß' => 'ss'],
        'fr' => ['œ' => 'oe', 'æ' => 'ae', 'ç' => 'c'],
        'es' => ['ñ' => 'n', 'Ñ' => 'N'],
    ];

    if (!empty($languageMap[$language])) {
        $string = str_replace(
            array_keys($languageMap[$language]),
            array_values($languageMap[$language]),
            $string
        );
    }

    // 3. Transliterate Unicode characters to ASCII (requires intl extension)
    if (function_exists('transliterator_transliterate')) {
        $string = transliterator_transliterate(
            'Any-Latin; Latin-ASCII; Lower()',
            $string
        );
    } else {
        // Fallback: use iconv if intl is not available
        $string = iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $string);
        $string = strtolower($string);
    }

    // 4. Replace common special characters with readable equivalents
    $specialChars = [
        '&'  => 'and',
        '@'  => 'at',
        '%'  => 'percent',
        '#'  => 'hash',
        '+'  => 'plus',
        '='  => 'equals',
        '/'  => $separator,
        '\\' => $separator,
    ];
    $string = str_replace(
        array_keys($specialChars),
        array_values($specialChars),
        $string
    );

    // 5. Replace any non-alphanumeric characters with the separator
    $string = preg_replace('/[^a-z0-9\s' . preg_quote($separator, '/') . ']/u', '', $string);

    // 6. Replace whitespace and multiple separators with a single separator
    $string = preg_replace('/[\s_]+/', $separator, $string);
    $string = preg_replace('/' . preg_quote($separator, '/') . '+/', $separator, $string);

    // 7. Trim separators from the beginning and end
    $string = trim($string, $separator);

    return $string;
}
