/**
 * Converts a string into a URL-safe slug.
 *
 * @param  string $string    The input string to slugify.
 * @param  string $separator The separator character (default: '-').
 * @return string            The slugified string.
 */
function slugify(string $string, string $separator = '-'): string
{
    if (empty(trim($string))) {
        return '';
    }

    // 1. Convert to UTF-8 if not already encoded
    $string = mb_convert_encoding($string, 'UTF-8', mb_detect_encoding($string));

    // 2. Transliterate accented/special characters to ASCII equivalents
    //    e.g., é → e, ñ → n, ü → u, ø → o
    $string = transliterator_transliterate('Any-Latin; Latin-ASCII', $string);

    // 3. Convert to lowercase
    $string = mb_strtolower($string, 'UTF-8');

    // 4. Replace non-alphanumeric characters (except separator) with separator
    $string = preg_replace('/[^a-z0-9\s' . preg_quote($separator, '/') . ']/', '', $string);

    // 5. Replace whitespace and multiple separators with a single separator
    $string = preg_replace('/[\s' . preg_quote($separator, '/') . ']+/', $separator, $string);

