```php
<?php

class ShoppingCart
{
    private array $items = [];

    /**
     * Add an item to the cart.
     *
     * @param string $name
     * @param float $price
     * @param int $quantity
     * @return void
     */
    public function addItem(string $name, float $price, int $quantity = 1): void
    {
        if ($price < 0 || $quantity < 1) {
            throw new InvalidArgumentException('Price must be >= 0 and quantity must be >= 1.');
        }

        if (isset($this->items[$name])) {
            $this->items[$name]['quantity'] += $quantity;
        } else {
            $this->items[$name] = [
                'price' => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Remove an item completely from the cart.
     *
     * @param string $name
     * @return void
     */
    public function removeItem(string $name): void
    {
        unset($this->items[$name]);
    }

    /**
     * Get the total cost of all items in the cart.
     *
     * @return float
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        return $total;
    }

    /**
     * Optional: get all items in the cart.
     *
     * @return array
     */
    public function getItems(): array
    {
        return $this->items;
    }
}
```

