```php
$cart = new ShoppingCart();

$cart->addItem('Apple', 1.50, 3);
$cart->addItem('Bread', 2.25, 2);

echo $cart->getTotal(); // 9.00

$cart->removeItem('Apple');

echo $cart->getTotal(); // 4.50
```

