```php
<?php

/**
 * A simple ShoppingCart class to manage items and calculate the total price.
 */
class ShoppingCart
{
    /**
     * The array to store cart items.
     * The structure is: ['itemId' => ['name' => 'Item Name', 'price' => 10.99, 'quantity' => 2]]
     *
     * @var array
     */
    private array $items = [];

    /**
     * Adds an item to the shopping cart.
     * If the item already exists, its quantity is increased.
     *
     * @param string $itemId A unique identifier for the item.
     * @param string $name The name of the item.
     * @param float $price The price of a single unit of the item.
     * @param int $quantity The number of units to add.
     */
    public function addItem(string $itemId, string $name, float $price, int $quantity = 1): void
    {
        if ($quantity <= 0) {
            // Do not add items with zero or negative quantity.
            return;
        }

        // Check if the item already exists in the cart
        if (isset($this->items[$itemId])) {
            // If it exists, just update the quantity
            $this->items[$itemId]['quantity'] += $quantity;
        } else {
            // If it's a new item, add it to the cart
            $this->items[$itemId] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Removes an item or decreases its quantity from the shopping cart.
     * If the quantity to remove is greater than or equal to the existing quantity,
     * the item is removed completely.
     *
     * @param string $itemId The unique identifier of the item to remove.
     * @param int $quantity The number of units to remove.
     */
    public function removeItem(string $itemId, int $quantity = 1): void
    {
        if ($quantity <= 0) {
            return;
        }

        // Check if the item exists in the cart
        if (isset($this->items[$itemId])) {
            // Decrease the quantity
            $this->items[$itemId]['quantity'] -= $quantity;

            // If quantity drops to 0 or less, remove the item from the cart
            if ($this->items[$itemId]['quantity'] <= 0) {
                unset($this->items[$itemId]);
            }
        }
    }

    /**
     * Calculates and returns the total price of all items in the cart.
     *
     * @return float The total price.
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        return $total;
    }

    /**
     * Gets all the items currently in the cart.
     *
     * @return array The list of items.
     */
    public function getItems(): array
    {
        return $this->items;
    }

    /**
     * Clears all items from the shopping cart.
     */
    public function clear(): void
    {
        $this->items = [];
    }
}

