### The `ShoppingCart` Class

This class uses an associative array to store items, where the product ID is the key. This makes it very efficient to check for, update, or remove existing items.

```php
<?php

/**
 * A simple ShoppingCart class to manage items and calculate the total.
 */
class ShoppingCart
{
    /**
     * The array to store cart items.
     * The structure will be: [productId => ['name' => '...', 'price' => ..., 'quantity' => ...]]
     *
     * @var array
     */
    private array $items = [];

    /**
     * Adds an item to the shopping cart.
     * If the item already exists, its quantity is updated.
     *
     * @param string|int $productId The unique identifier for the product.
     * @param string $name The name of the product.
     * @param float $price The price of a single unit of the product.
     * @param int $quantity The number of units to add.
     * @return void
     */
    public function addItem($productId, string $name, float $price, int $quantity = 1): void
    {
        // Basic validation
        if ($quantity <= 0 || $price < 0) {
            // Or throw an exception, depending on desired error handling
            return;
        }

        // If the item is already in the cart, just update the quantity
        if (isset($this->items[$productId])) {
            $this->items[$productId]['quantity'] += $quantity;
        } else {
            // Otherwise, add the new item to the cart
            $this->items[$productId] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Removes an item completely from the shopping cart.
     *
     * @param string|int $productId The ID of the product to remove.
     * @return bool True if the item was removed, false if it was not in the cart.
     */
    public function removeItem($productId): bool
    {
        if (isset($this->items[$productId])) {
            unset($this->items[$productId]);
            return true;
        }
        return false;
    }

    /**
     * Updates the quantity of a specific item in the cart.
     * If the quantity is set to 0 or less, the item is removed.
     *
     * @param string|int $productId The ID of the product to update.
     * @param int $quantity The new quantity.
     * @return bool True on success, false if the item is not in the cart.
     */
    public function updateQuantity($productId, int $quantity): bool
    {
        if (!isset($this->items[$productId])) {
            return false;
        }

        if ($quantity <= 0) {
            $this->removeItem($productId);
        } else {
            $this->items[$productId]['quantity'] = $quantity;
        }

        return true;
    }

    /**
     * Calculates the total price of all items in the cart.
     *
     * @return float The total price.
     */
    public function getTotal(): float
    {
        $total = 0.0;
        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }
        return $total;
    }

    /**
     * Gets all items currently in the cart.
     *
     * @return array The array of cart items.
     */
    public function getItems(): array
    {
        return $this->items;
    }

    /**
     * Clears all items from the shopping cart.
     *
     * @return void
     */
    public function clear(): void
    {
        $this->items = [];
    }
}
