/**
 * A simple ShoppingCart class to manage items and calculate the total.
 */
class ShoppingCart
{
    /**
     * The array of items in the shopping cart.
     * The key is the product ID.
     * The value is an associative array with 'name', 'price', and 'quantity'.
     *
     * @var array
     */
    private array $items = [];

    /**
     * Adds an item to the shopping cart.
     * If the item already exists, it updates the quantity.
     *
     * @param string $productId A unique identifier for the product.
     * @param string $name The name of the product.
     * @param float $price The price of a single unit of the product.
     * @param int $quantity The number of units to add.
     * @return void
     */
    public function addItem(string $productId, string $name, float $price, int $quantity = 1): void
    {
        // Basic validation
        if ($quantity <= 0 || $price < 0) {
            // Or throw an exception, depending on desired error handling
            return;
        }

        // If the item is already in the cart, just increase the quantity
        if (isset($this->items[$productId])) {
            $this->items[$productId]['quantity'] += $quantity;
        } else {
            // Otherwise, add the new item to the cart
            $this->items[$productId] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Removes an item completely from the shopping cart.
     *
     * @param string $productId The ID of the product to remove.
     * @return void
     */
    public function removeItem(string $productId): void
    {
        if (isset($this->items[$productId])) {
            unset($this->items[$productId]);
        }
    }

    /**
     * Updates the quantity of a specific item in the cart.
     * If the new quantity is 0 or less, the item is removed.
