### The `ShoppingCart` Class

This class uses an associative array to store items, where the product ID is the key. This makes it very efficient to check for, add, or update the quantity of an existing item.

```php
<?php

/**
 * A simple ShoppingCart class to manage items and calculate the total price.
 */
class ShoppingCart
{
    /**
     * @var array The items in the shopping cart.
     * The structure is: ['productId' => ['name' => 'Item Name', 'price' => 10.00, 'quantity' => 1]]
     */
    private array $items = [];

    /**
     * Adds an item to the shopping cart.
     * If the item already exists, its quantity is updated.
     *
     * @param string $productId The unique identifier of the product.
     * @param string $name The name of the product.
     * @param float $price The price of a single unit of the product.
     * @param int $quantity The number of units to add (defaults to 1).
     */
    public function addItem(string $productId, string $name, float $price, int $quantity = 1): void
    {
        // Basic validation
        if ($price <= 0 || $quantity <= 0) {
            // Or throw an InvalidArgumentException
            return;
        }

        // If the item is already in the cart, just increase the quantity
        if (isset($this->items[$productId])) {
            $this->items[$productId]['quantity'] += $quantity;
        } else {
            // Otherwise, add the new item to the cart
            $this->items[$productId] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity
            ];
        }
    }

    /**
     * Removes an item from the shopping cart or decreases its quantity.
     *
     * @param string $productId The unique identifier of the product to remove.
     * @param int $quantity The number of units to remove. If quantity is greater
     *                      than or equal to the item's quantity, the item is removed completely.
     */
    public function removeItem(string $productId, int $quantity = 1): void
    {
        // Check if the item exists in the cart
        if (isset($this->items[$productId])) {
            // Decrease the quantity
            $this->items[$productId]['quantity'] -= $quantity;

            // If the quantity is zero or less, remove the item completely
            if ($this->items[$productId]['quantity'] <= 0) {
                unset($this->items[$productId]);
            }
        }
    }

    /**
     * Calculates the total price of all items in the cart.
     *
     * @return float The total price.
     */
    public function getTotal(): float
    {
        $total = 0.0;
        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }
        return $total;
    }

    /**
     * Gets all the items currently in the cart.
     *
     * @return array The list of items.
     */
    public function getItems(): array
    {
        return $this->items;
    }

    /**
     * Empties the shopping cart.
     */
    public function clear(): void
    {
        $this->items = [];
    }
}
