<?php

/**
 * A simple ShoppingCart class to manage items and calculate the total price.
 */
class ShoppingCart
{
    /**
     * @var array The array to store cart items.
     */
    private array $items = [];

    /**
     * Adds an item to the shopping cart.
     * If the item already exists, its quantity is updated.
     *
     * @param string $productId A unique identifier for the product.
     * @param string $name The name of the product.
     * @param float $price The price of a single unit of the product.
     * @param int $quantity The number of units to add.
     */
    public function addItem(string $productId, string $name, float $price, int $quantity = 1): void
    {
        // Basic validation
        if ($quantity <= 0 || $price < 0) {
            return; // Do not add items with invalid quantity or price
        }

        if (isset($this->items[$productId])) {
            // If item already exists, just update the quantity
            $this->items[$productId]['quantity'] += $quantity;
        } else {
            // Add new item to the cart
            $this->items[$productId] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }
    }

    /**
     * Removes an item completely from the shopping cart.
     *
     * @param string $productId The unique identifier of the product to remove.
     */
    public function removeItem(string $productId): void
    {
        if (isset($this->items[$productId])) {
            unset($this->items[$productId]);
        }
    }

    /**
     * Calculates and returns the total price of all items in the cart.
     *
     * @return float The total price.
     */
    public function getTotal(): float
    {
        $total = 0.0;

        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }

        return $total;
    }

    /**
     * A helper method to view the current items in the cart.
     *
     * @return array
     */
    public function getItems(): array
    {
        return $this->items;
    }
}
