### The `ShoppingCart` Class

This class uses an internal associative array to store items, where the product ID is the key. This makes it efficient to find, update, and remove items.

```php
<?php

/**
 * A simple Shopping Cart class.
 *
 * This class provides the basic functionality for a shopping cart,
 * allowing you to add items, remove items, and calculate the total cost.
 */
class ShoppingCart
{
    /**
     * The array to store cart items.
     * The structure is:
     * [
     *     'product_id' => [
     *         'name'     => 'Product Name',
     *         'price'    => 10.99,
     *         'quantity' => 2
     *     ],
     *     // ... more items
     * ]
     *
     * @var array
     */
    private array $items = [];

    /**
     * Adds an item to the shopping cart.
     *
     * If the item already exists in the cart, its quantity is increased.
     * Otherwise, the item is added as a new entry.
     *
     * @param string $productId The unique identifier of the product.
     * @param string $name The name of the product.
     * @param float $price The price of a single unit of the product.
     * @param int $quantity The number of units to add.
     * @return self Allows for method chaining.
     */
    public function addItem(string $productId, string $name, float $price, int $quantity = 1): self
    {
        // Basic validation for price and quantity
        if ($price < 0 || $quantity <= 0) {
            // In a real application, you might throw an InvalidArgumentException
            echo "Error: Price and quantity must be positive values.\n";
            return $this;
        }

        if (isset($this->items[$productId])) {
            // Item already exists, just update the quantity
            $this->items[$productId]['quantity'] += $quantity;
        } else {
            // Add a new item to the cart
            $this->items[$productId] = [
                'name'     => $name,
                'price'    => $price,
                'quantity' => $quantity,
            ];
        }

        return $this; // Return the object instance for method chaining
    }

    /**
     * Removes an item from the shopping cart.
     *
     * If a quantity is specified, it reduces the item's quantity. If the
     * quantity becomes zero or less, the item is removed completely.
     * If no quantity is specified, the entire item is removed from the cart.
     *
     * @param string $productId The unique identifier of the product to remove.
     * @param int|null $quantity The number of units to remove. If null, removes the entire item.
     * @return self Allows for method chaining.
     */
    public function removeItem(string $productId, ?int $quantity = null): self
    {
        if (!isset($this->items[$productId])) {
            // Item not in cart, do nothing.
            return $this;
        }

        if ($quantity === null) {
            // If no quantity is specified, remove the entire item.
            unset($this->items[$productId]);
        } else {
            // Reduce the quantity of the item
            $this->items[$productId]['quantity'] -= $quantity;

            // If quantity drops to 0 or below, remove the item completely.
            if ($this->items[$productId]['quantity'] <= 0) {
                unset($this->items[$productId]);
            }
        }

        return $this;
    }

    /**
     * Calculates and returns the total price of all items in the cart.
     *
     * @return float The total cost of all items.
     */
    public function getTotal(): float
    {
        $total = 0.0;
        foreach ($this->items as $item) {
            $total += $item['price'] * $item['quantity'];
        }
        return $total;
    }

    /**
     * Returns the current items in the cart.
     *
     * @return array The array of items in the cart.
     */
    public function getItems(): array
    {
        return $this->items;
    }
}

